cd /testbed && source /opt/miniconda3/bin/activate testbed && python3 << 'EOF'
import cantools

# Let's try different start positions
# Maybe Temperature should start at a different bit
for temp_start in range(0, 64, 4):
    for radius_start in range(temp_start + 12, 64, 4):
        for enable_start in range(radius_start + 6, 64, 4):
            dbc_string = f'''
VERSION "1.0"

BU_: PCM1 FOO

BO_ 496 ExampleMessage: 8 PCM1
 SG_ Temperature : {temp_start}|12@1+ (0.01,250) [229.52|270.47] "degK"  PCM1,FOO
 SG_ AverageRadius : {radius_start}|6@1+ (0.1,0) [0|5] "m" Vector__XXX
 SG_ Enable : {enable_start}|1@1+ (1,0) [0|0] "-" Vector__XXX

VAL_ 496 Enable 0 "Disabled" 1 "Enabled" ;
'''
            try:
                db = cantools.db.load_string(dbc_string)
                encoded = db.encode_message(496, {'Temperature': 250.55, 'AverageRadius': 3.2, 'Enable': 1})
                if encoded.hex() == 'c006e00000000000':
                    print(f"FOUND! temp_start={temp_start}, radius_start={radius_start}, enable_start={enable_start}")
                    print(f"Encoded: {encoded.hex()}")
                    break
            except Exception as e:
                pass
        else:
            continue
        break
    else:
        continue
    break
else:
    print("Not found with Motorola byte order")

# Let's also try Intel byte order
for temp_start in range(0, 64, 4):
    for radius_start in range(temp_start + 12, 64, 4):
        for enable_start in range(radius_start + 6, 64, 4):
            dbc_string = f'''
